// C++17
#include <cstdint>
#include <cstddef>
#include <cstring>
#include <type_traits>

// A "plain old data" wire message: fixed-width integers only, no owning members.
struct Tick {
    std::int64_t ts;   // timestamp  (8 bytes, alignment 8)
    std::int32_t px;   // price      (4 bytes)
    std::int32_t qty;  // quantity   (4 bytes)
};

// Trivially copyable == the object's value is fully described by its bytes,
// so std::memcpy / std::bit_cast on it is well-defined (no owning pointers).
static_assert(std::is_trivially_copyable_v<Tick>, "must be memcpy-able");
// Standard-layout == C-compatible layout (members laid out in order, one access
// control), which is what lets the byte image be shared with other languages.
static_assert(std::is_standard_layout_v<Tick>,    "C-compatible layout");

std::size_t serialize(const Tick& t, std::byte* out) {
    // memcpy reads sizeof(Tick) bytes from &t and writes them to out.
    // Legal precisely because Tick is trivially copyable.
    std::memcpy(out, &t, sizeof(Tick));
    // Report how many bytes we produced so the caller can advance its cursor.
    return sizeof(Tick);
}
