// C++17
#include <type_traits>

// Scoped enum with a pinned 1-byte underlying type, mirroring a one-byte wire tag.
enum class MsgType : char {
    NewOrder  = 'N',
    Cancel    = 'C',
    Execution = 'E',
};
static_assert(sizeof(MsgType) == 1);  // ': char' guarantees exactly one byte

// Hand-rolled std::to_underlying (which only exists since C++23).
template <class E>
constexpr auto to_underlying(E e) noexcept {
    // underlying_type_t<E> is 'char' here; the cast strips the enum's type safety.
    return static_cast<std::underlying_type_t<E>>(e);
}

const char* name(MsgType m) {
    switch (m) {                 // build with -Wswitch -Werror to catch new cases
        case MsgType::NewOrder:  return "NewOrder";
        case MsgType::Cancel:    return "Cancel";
        case MsgType::Execution: return "Execution";
        // No 'default': adding a 4th enumerator makes -Wswitch flag this switch.
    }
    return "?";                  // reached only for an out-of-range cast-in value
}
