```cpp
// C++17
#include <cstddef>
#include <utility>   // std::swap

void reverse_in_place(int* a, std::size_t n) {
    if (n == 0) return;                // guard: a + n - 1 would underflow for n==0
    int* left  = a;                    // first element
    int* right = a + n - 1;            // last element
    while (left < right) {             // stop when the pointers meet/cross
        std::swap(*left, *right);      // exchange the pair at the two ends
        ++left;                        // walk inward from the front
        --right;                       // walk inward from the back
    }
}
```

