// C++17
template <class T>
T max3(const T& a, const T& b, const T& c) {
    // Pick the larger of the first two by reference (no copy yet)...
    const T& m = (a > b) ? a : b;
    // ...then compare that against the third and return the winner by value.
    return (m > c) ? m : c;
}

// Each distinct T stamps out a separate function (monomorphization):
//   max3(1, 2, 3)        -> max3<int>
//   max3(1.5, 0.5, 9.0)  -> max3<double>   (a SEPARATE function in the binary)
