// C++14
constexpr unsigned long long factorial(unsigned n) {
    unsigned long long r = 1;            // accumulator; mutating a local is legal in C++14 constexpr
    for (unsigned i = 2; i <= n; ++i)    // loop: also a C++14 relaxation (C++11 forbade it)
        r *= i;                          // multiply in each factor
    return r;                            // 0! and 1! fall through with r == 1
}

