static void check(const char* n, bool ok, const char* detail){
    printf("__CASE__|%s|%s|%s\n", n, ok?"PASS":"FAIL", detail);
}

// A trivially-copyable POD -> should take the memcpy fast path.
struct Pod { std::int32_t a; std::int32_t b; };

// A non-trivial type with its OWN serialize -> should take the slow path.
struct Custom {
    std::int32_t v;
    Custom(std::int32_t x) : v(x) {}
    // A user-declared copy ctor makes Custom NOT trivially copyable.
    Custom(const Custom& o) : v(o.v) {}
    void serialize(std::byte* out) const {
        // Write a tagged, byte-swapped form so we can tell the slow path ran.
        out[0] = std::byte{0xCC};               // marker
        std::int32_t flipped = -v;
        std::memcpy(out + 1, &flipped, sizeof flipped);
    }
};

int main(){
    static_assert(std::is_trivially_copyable_v<Pod>, "Pod should be trivial");
    static_assert(!std::is_trivially_copyable_v<Custom>, "Custom should be non-trivial");

    {
        Pod p{0x11111111, 0x22222222};
        std::byte buf[sizeof(Pod)];
        serialize(buf, p);
        bool ok = std::memcmp(buf, &p, sizeof(Pod)) == 0;  // fast path == raw bytes
        check("trivial-fastpath", ok, ok?"memcpy bytes match":"bytes differ");
    }
    {
        Custom c{5};
        std::byte buf[8] = {};
        serialize(buf, c);                                  // must dispatch to c.serialize
        std::int32_t got; std::memcpy(&got, buf+1, sizeof got);
        bool ok = (buf[0]==std::byte{0xCC}) && (got == -5);
        char d[48]; std::snprintf(d,sizeof d,"marker=%u got=%d want=-5",(unsigned)buf[0],got);
        check("custom-slowpath", ok, d);
    }
