        // Another trivial type: a fixed array wrapper.
        struct Vec3 { double x,y,z; } v{1.0,2.0,3.0};
        std::byte buf[sizeof(Vec3)];
        serialize(buf, v);
        bool ok = std::memcmp(buf, &v, sizeof(Vec3)) == 0;
        check("trivial-doubles", ok, ok?"3 doubles copied":"mismatch");
