// C++17
#include <type_traits>
#include <cstddef>
#include <cstring>

template <class T>
void serialize(std::byte* out, const T& v) {
    if constexpr (std::is_trivially_copyable_v<T>) {
        // Compiled ONLY when T is trivial: the value is its bytes, so memcpy is valid.
        std::memcpy(out, &v, sizeof v);
    } else {
        // Compiled ONLY otherwise: defer to the type's own member serializer.
        // (v has no usable raw byte image, so we must ask it how to flatten itself.)
        v.serialize(out);
    }
}
