// C++17
#include <vector>
#include <algorithm>

void remove_zeros(std::vector<int>& v) {
    // std::remove moves the kept (non-zero) elements to the front, preserving order,
    // and returns an iterator to the new logical end. vector::erase then drops the
    // leftover tail in one shot -- a single O(n) pass, no per-element shifting.
    v.erase(std::remove(v.begin(), v.end(), 0), v.end());
}

// C++20 one-liner that does the same thing:
//   std::erase(v, 0);
