// C++17
#include <queue>
#include <vector>
#include <functional>

std::vector<long> drain_sorted(std::vector<long> timestamps) {
    // std::greater flips the comparison so the SMALLEST value is the heap's "top":
    // this turns the default max-heap into a min-heap.
    std::priority_queue<long, std::vector<long>, std::greater<long>> events;
    for (long t : timestamps)
        events.push(t);                  // O(log n) each

    std::vector<long> out;
    out.reserve(timestamps.size());
    while (!events.empty()) {
        out.push_back(events.top());     // smallest remaining (O(1) read)
        events.pop();                    // pop() returns void, so read top() first
    }
    return out;                          // now in ascending order
}
