// C++17
#include <vector>
#include <utility>
#include <optional>
#include <algorithm>

std::optional<double> find_price(const std::vector<std::pair<int,double>>& book, int key) {
    // Comparator projects each pair down to its .first so lower_bound compares keys.
    auto by_key = [](const std::pair<int,double>& e, int k){ return e.first < k; };
    // lower_bound returns the first element whose key is NOT < key (i.e. >= key).
    auto it = std::lower_bound(book.begin(), book.end(), key, by_key);
    // It is a hit only if we landed on a real element AND its key matches exactly.
    if (it != book.end() && it->first == key)
        return it->second;
    return std::nullopt;                 // not present
}
