// C++17
#include <cstddef>
#include <utility>

class Engine {
    int*        data_ = nullptr;   // owned heap buffer
    std::size_t n_    = 0;         // element count
public:
    // Allocate n value-initialized (zeroed) ints. 'explicit' blocks Engine e = 4;
    explicit Engine(std::size_t n) : data_(new int[n]{}), n_(n) {}
    ~Engine() { delete[] data_; }  // delete[] on nullptr is a safe no-op

    Engine(const Engine&)            = delete;   // forbid copying -> move-only
    Engine& operator=(const Engine&) = delete;

    // Move ctor: take ownership of o's buffer, then leave o empty but destructible.
    Engine(Engine&& o) noexcept
        : data_(o.data_), n_(o.n_) {
        o.data_ = nullptr; o.n_ = 0;
    }
    // Move assign: release our buffer, steal o's, null o. Self-move guard avoids
    // deleting the very buffer we are about to take.
    Engine& operator=(Engine&& o) noexcept {
        if (this != &o) {
            delete[] data_;
            data_ = o.data_; n_ = o.n_;
            o.data_ = nullptr; o.n_ = 0;
        }
        return *this;
    }

    std::size_t size() const { return n_; }
    int&       at(std::size_t i)       { return data_[i]; }
    int        at(std::size_t i) const { return data_[i]; }
    bool moved_from() const { return data_ == nullptr; }
};
