// C++20
#include <compare>

struct Price {
    long ticks = 0;

    // Compound assignment is the primitive; takes rhs by value (Price is cheap).
    Price& operator+=(Price rhs) noexcept {
        ticks += rhs.ticks;
        return *this;            // returns *this so it composes like built-in +=
    }

    // Defaulted three-way compare over an integral member -> std::strong_ordering,
    // a total order usable by std::set/std::map/std::sort.
    auto operator<=>(const Price&) const = default;
    bool operator==(const Price&) const = default;
};

// Binary + built ON TOP of += so the two can never disagree.
// lhs is taken BY VALUE, so it is our own scratch copy to mutate and return.
inline Price operator+(Price lhs, Price rhs) noexcept {
    lhs += rhs;        // reuse the member
    return lhs;        // return by value -> a fresh Price (never a reference)
}
