// 'overloaded' inherits operator() from every lambda it is built from.
// The pack-expanded using-declaration brings each lambda's call operator into scope.
template <class... Ts> struct overloaded : Ts... { using Ts::operator()...; };
// C++17 deduction guide so we can brace-construct overloaded{ lambdas... }.
template <class... Ts> overloaded(Ts...) -> overloaded<Ts...>;

char on_message(const Msg& m) {
    // std::visit picks the arm whose parameter matches the active alternative.
    return std::visit(overloaded{
        [](const AddOrder&)    { return 'A'; },
        [](const CancelOrder&) { return 'C'; },
        [](const Trade&)       { return 'T'; },
    }, m);
    // Add a 4th alternative to Msg and this visit fails to compile until handled.
